// src/utils/project.ts
import fs from "fs-extra";
import path from "path";
async function detectProject(cwd) {
  const info = {
    framework: "unknown",
    hasTypeScript: false,
    hasSrcDir: false,
    packageManager: "npm",
    serverEntry: "index.js",
    serverType: "unknown"
  };
  const packageJsonPath = path.join(cwd, "package.json");
  if (await fs.pathExists(packageJsonPath)) {
    const packageJson = await fs.readJson(packageJsonPath);
    if (packageJson.dependencies?.express || packageJson.devDependencies?.express) {
      info.framework = "express";
      info.serverType = "express";
    }
    if (packageJson.dependencies?.fastify || packageJson.devDependencies?.fastify) {
      info.framework = "fastify";
      info.serverType = "fastify";
    }
    if (info.framework === "unknown" && (packageJson.dependencies?.cors || packageJson.dependencies?.helmet || packageJson.dependencies?.morgan || packageJson.dependencies?.["body-parser"] || packageJson.scripts?.start || packageJson.scripts?.dev || packageJson.scripts?.server)) {
      info.framework = "node";
      info.serverType = "vanilla";
    }
    if (packageJson.dependencies?.typescript || packageJson.devDependencies?.typescript || packageJson.devDependencies?.["@types/node"]) {
      info.hasTypeScript = true;
    }
    if (packageJson.main) {
      info.serverEntry = packageJson.main;
    } else if (packageJson.scripts?.start) {
      const startScript = packageJson.scripts.start;
      if (startScript.includes("server.js")) {
        info.serverEntry = "server.js";
      } else if (startScript.includes("app.js")) {
        info.serverEntry = "app.js";
      } else if (startScript.includes("index.js")) {
        info.serverEntry = "index.js";
      }
    }
  }
  const tsConfigPath = path.join(cwd, "tsconfig.json");
  if (await fs.pathExists(tsConfigPath)) {
    info.hasTypeScript = true;
    if (info.serverEntry.endsWith(".js")) {
      info.serverEntry = info.serverEntry.replace(".js", ".ts");
    }
  }
  const srcDir = path.join(cwd, "src");
  info.hasSrcDir = await fs.pathExists(srcDir);
  const possibleEntries = [
    "app.js",
    "app.ts",
    "server.js",
    "server.ts",
    "index.js",
    "index.ts",
    "main.js",
    "main.ts"
  ];
  for (const entry of possibleEntries) {
    const entryPath = info.hasSrcDir ? path.join(cwd, "src", entry) : path.join(cwd, entry);
    if (await fs.pathExists(entryPath)) {
      info.serverEntry = entry;
      if (entry.endsWith(".ts")) {
        info.hasTypeScript = true;
      }
      break;
    }
  }
  if (await fs.pathExists(path.join(cwd, "pnpm-lock.yaml"))) {
    info.packageManager = "pnpm";
  } else if (await fs.pathExists(path.join(cwd, "yarn.lock"))) {
    info.packageManager = "yarn";
  } else if (await fs.pathExists(path.join(cwd, "bun.lockb"))) {
    info.packageManager = "bun";
  } else {
    info.packageManager = "npm";
  }
  return info;
}

